const alerts = $('Get New Alerts').all().map(i => i.json);
const threats = $('Get Watching Threats').all().map(i => i.json);
const investigations = $('Get Open Investigations').all().map(i => i.json);

const bySeverity = {};
alerts.forEach(a => {
  const s = a.severity || 'unknown';
  bySeverity[s] = (bySeverity[s] || 0) + 1;
});

const byIP = {};
alerts.forEach(a => {
  if (a.ip_address) {
    byIP[a.ip_address] = (byIP[a.ip_address] || 0) + 1;
  }
});
const topIPs = Object.entries(byIP)
  .map(([ip, count]) => ({ ip, count }))
  .sort((a, b) => b.count - a.count)
  .slice(0, 5);

const alertSummary = alerts.slice(0, 20).map(a => 
  `- [${a.severity}] ${a.title} | IP: ${a.ip_address}`
).join('\n');

const threatSummary = threats.map(t => 
  `- ${t.threat_type} từ ${t.ip_address} (${t.country}) | ${t.hits} hits | ${t.severity}`
).join('\n');

const investigationSummary = investigations.map(i => 
  `- [${i.severity}] ${i.code}: ${i.title} | Progress: ${i.progress}%`
).join('\n');

return [{
  json: {
    time_window: '1h',
    alert_count: alerts.length,
    threats_count: threats.length,
    investigations_count: investigations.length,
    by_severity: bySeverity,
    top_ips: topIPs,
    alerts_text: alertSummary || 'Không có alert mới',
    threats_text: threatSummary || 'Không có threat đang watching',
    investigations_text: investigationSummary || 'Không có investigation đang mở'
  }
}];

const response = $json;
const text = response.candidates?.[0]?.content?.parts?.[0]?.text || '';

let jsonText = text.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();

let parsed;
try {
  const jsonMatch = jsonText.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    parsed = JSON.parse(jsonMatch[0]);
  } else {
    throw new Error('Không tìm thấy JSON');
  }
} catch (e) {
  parsed = {
    summary: text.slice(0, 500) || 'Không parse được response',
    top_threat: { type: 'unknown', ip: 'unknown', severity: 'medium', description: 'Không parse được' },
    affected_targets: [],
    recommendation: 'Cần review thủ công',
    risk_level: 'medium'
  };
}

const agg = $('Aggregate Data').item.json;

return [{
  json: {
    time_window: agg.time_window,
    alert_count: agg.alert_count,
    threats_count: agg.threats_count,
    investigations_count: agg.investigations_count,
    summary: parsed.summary,
    top_threat: parsed.top_threat,
    affected_targets: parsed.affected_targets,
    recommendation: parsed.recommendation,
    risk_level: parsed.risk_level
  }
}];

